907	// findRecordIn 在给定结算历史中按编号查找成功记录。
908	func findRecordIn(records []Record, id string) (Record, bool) {
909		// 记录按成功顺序追加且 ID 唯一；单机账本量级直接扫描。
910		for _, r := range records {
911			if r.ID == id {
912				return r, true
913			}
914		}
915		return Record{}, false
916	}
