	spent := map[string]bool{}
	s := Execute(Intent{ID: "a", State: "pending", Amount: 10000}, 10, spent, 20000)
	if s.Status != "settled" || s.Charged != 10010 || s.FeeBps != 10 || s.Ref != "settle:a" || !spent["a"] {
		t.Fatalf("settle: %+v spent=%v", s, spent)
	}
}

